DROP TABLE IF EXISTS `system_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类编号',
  `name` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类编码',
  `category_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT '分类类型：area-区域分类, facility-设施分类, status-状态分类, brand-品牌分类, department-部门分类, role-角色分类, field-字段分类',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父分类编号',
  `sort` int NOT NULL DEFAULT '0' COMMENT '显示顺序',
  `icon` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类图标',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类颜色',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类描述',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `tree_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '树路径，如 0/1/2',
  `level` int NOT NULL DEFAULT '1' COMMENT '层级深度',
  `readonly` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否系统只读，1=只读（禁止删除/改名）',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_tenant_deleted` (`code`,`tenant_id`,`deleted`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_tree_path` (`tree_path`),
  KEY `idx_category_type` (`category_type`),
  KEY `idx_status` (`status`),
  KEY `idx_category_status` (`category_type`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=196 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='分类表';
