--
-- Table structure for table `system_directory`
--

DROP TABLE IF EXISTS `system_directory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_directory` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '目录ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `business_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `parent_id` bigint DEFAULT '0' COMMENT '父目录ID（0表示根目录）',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目录名称',
  `code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目录编码',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图标',
  `sort` int DEFAULT '0' COMMENT '排序号',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态（0:禁用，1:启用）',
  `ext_data` text COLLATE utf8mb4_unicode_ci COMMENT '扩展属性（JSON格式）',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_business_code` (`tenant_id`,`business_type`,`code`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_business_type` (`business_type`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_sort` (`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用目录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `system_directory`
--

LOCK TABLES `system_directory` WRITE;
/*!40000 ALTER TABLE `system_directory` DISABLE KEYS */;
