DROP TABLE IF EXISTS `system_item_category_rel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_item_category_rel` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `item_id` bigint NOT NULL COMMENT '数据项ID',
  `item_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据项类型：device-设备, product-产品, user-用户, field_def-字段定义',
  `category_id` bigint NOT NULL COMMENT '分类ID',
  `category_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类类型：area-区域分类, facility-设施分类, status-状态分类, brand-品牌分类, department-部门分类, role-角色分类, field-字段分类',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_item_category` (`item_id`,`item_type`,`category_id`,`deleted`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_item_type` (`item_type`),
  KEY `idx_category_type` (`category_type`),
  KEY `idx_item_category_type` (`item_type`,`category_type`),
  KEY `idx_category_item_type` (`category_type`,`item_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统-数据分类关联表';
