DROP TABLE IF EXISTS `system_page_build_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_page_build_record` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '构建记录ID',
  `page_design_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面设计ID',
  `build_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '构建ID',
  `build_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'building' COMMENT '构建状态',
  `progress` int DEFAULT '0' COMMENT '构建进度(0-100)',
  `message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '构建消息',
  `start_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '完成时间',
  `error_message` text COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_build_id` (`build_id`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `idx_page_design_id` (`page_design_id`),
  KEY `idx_build_status` (`build_status`),
  KEY `idx_start_time` (`start_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='页面构建记录表';
